import org.junit.jupiter.api.Test;

class RepositoryConfigRepositoryTest {

	@Test
	void systemStatementsDoNotExposeStoredElasticsearchPassword() throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		RepositoryConfig config = mock(RepositoryConfig.class);
		when(manager.getRepositoryIDs()).thenReturn(Set.of("example"));
		when(manager.getRepositoryConfig("example")).thenReturn(config);
		when(manager.getLocation()).thenReturn(URI.create("http://localhost/rdf4j-server").toURL());
		doAnswer(invocation -> {
			Model model = invocation.getArgument(0);
			Resource subject = invocation.getArgument(1);
			model.add(subject, SimpleValueFactory.getInstance()
					.createIRI(
							"tag:rdf4j.org,2023:config/lucene.elasticsearch.http.password"),
					SimpleValueFactory.getInstance().createLiteral("private-password-marker"));
			model.add(subject, SimpleValueFactory.getInstance()
					.createIRI(
							"tag:rdf4j.org,2023:config/lucene.indexDir"),
					SimpleValueFactory.getInstance().createLiteral("/tmp/index"));
			return null;
		}).when(config).export(any(Model.class), any(Resource.class));

		RepositoryConfigRepository system = new RepositoryConfigRepository(manager);
		system.init();
		try (RepositoryConnection connection = system.getConnection();
				RepositoryResult<Statement> statements = connection.getStatements(null, null, null, false)) {
			List<String> values = new ArrayList<>();
			while (statements.hasNext()) {
				values.add(statements.next().getObject().stringValue());
			}
			assertThat(values).contains("/tmp/index").doesNotContain("private-password-marker");
		} finally {
			system.shutDown();
		}
	}
}
